#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include "amp.h"

/*
 * Read u32be.
 */

static uint32_t
read_u32_be(char *buf) {
  uint32_t n = 0;
  n |= buf[0] << 24;
  n |= buf[1] << 16;
  n |= buf[2] << 8;
  n |= buf[3];
  return n;
}

/*
 * Write u32be.
 */

static void
write_u32_be(char *buf, uint32_t n) {
  buf[0] = n >> 24 & 0xff;
  buf[1] = n >> 16 & 0xff;
  buf[2] = n >> 8 & 0xff;
  buf[3] = n & 0xff;
}

/*
 * Decode the `msg` header in `buf`.
 */

void
amp_decode(amp_t *msg, char *buf) {
  msg->version = buf[0] >> 4;
  msg->argc = buf[0] & 0xf;
  msg->buf = buf + 1;
}

